from pathlib import Path
import shutil, hashlib, json, argparse
parser=argparse.ArgumentParser(description="Instrument a new disposable copy; never edit the source checkout")
parser.add_argument('--root', type=Path, required=True)
parser.add_argument('--output', type=Path, required=True)
args=parser.parse_args()
root=args.root.resolve(strict=True)
copy=args.output.resolve()
copy.mkdir()
for name in ['Cargo.toml','Cargo.lock']:
 shutil.copy2(root/name,copy/name)
for name in ['src','tests']:
 shutil.copytree(root/name,copy/name)
manifest={str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for p in (root/'src').glob('*.rs')}
(copy.parent/'original-source.json').write_text(json.dumps(manifest,indent=2))
def edit(name,old,new,count=1):
 p=copy/'src'/name;s=p.read_text();actual=s.count(old)
 if actual!=count: raise RuntimeError(f'{name}: expected {count}, got {actual}: {old!r}')
 p.write_text(s.replace(old,new))
shutil.copy2(Path(__file__).with_name('profile.rs'),copy/'src/profile.rs')
with (copy/'src/lib.rs').open('a') as f: f.write('\npub mod profile;\n')
